import { NavLink } from "react-router-dom";
import React from 'react'; // اطمینان از وارد شدن React

function Nav() {
  return (
    <nav className="bottom-nav"> {/* کلاس nav را به bottom-nav تغییر می‌دهیم */}
      <NavLink to="/" className={({ isActive }) => (isActive ? "active-link" : "nav-link")}>
        <i className="fas fa-home"></i> {/* آیکون Home */}
        <span>خانه</span> {/* متن زیر آیکون */}
      </NavLink>
      
      <NavLink
        to="/Arsenal"
        className={({ isActive }) => (isActive ? "active-link" : "nav-link")}
      >
        <i className="fas fa-shield-alt"></i> {/* آیکون برای تیم (مثلا سپر) */}
        <span>آرسنال</span>
      </NavLink>

      <NavLink
        to="/football"
        className={({ isActive }) => (isActive ? "active-link" : "nav-link")}
      >
        <i className="fas fa-futbol"></i> {/* آیکون فوتبال */}
        <span>مسابقات</span>
      </NavLink>

      <NavLink
        to="/playergameplay"
        className={({ isActive }) => (isActive ? "active-link" : "nav-link")}
      >
        <i className="fas fa-user-alt"></i> {/* آیکون بازیکن (مثلا کاربر) */}
        <span>بازیکنان</span>
      </NavLink>
    </nav>
  );
}

export default Nav;