import React from 'react';
import competitionData from '../data/competitions.json'; // وارد کردن داده‌ها
import './football.css'; // وارد کردن استایل‌ها

const Football = () => {
  const { competitions } = competitionData;

  // تابعی برای فرمت‌دهی تاریخ
  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('fa-IR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
  };

  return (
    <div className="football-container">
      <h1 className="main-title">لیگ‌ها و مسابقات فوتبال</h1>
      <div className="competitions-grid">
        {competitions.map((comp) => (
          <div key={comp.id} className="competition-card">
            <div className="card-header">
              <img 
                src={comp.emblem} 
                alt={`${comp.name} emblem`} 
                className="competition-emblem" 
              />
              <div className="area-info">
                <img 
                  src={comp.area.flag} 
                  alt={`${comp.area.name} flag`} 
                  className="area-flag" 
                />
                <span className="area-name">{comp.area.name}</span>
              </div>
            </div>
            <div className="card-body">
              <h2 className="competition-name">{comp.name}</h2>
              <p className="season-info">
                <strong><i className="fas fa-calendar-alt"></i> تاریخ شروع:</strong> {formatDate(comp.currentSeason.startDate)}
              </p>
              <p className="season-info">
                <strong><i className="fas fa-calendar-check"></i> تاریخ پایان:</strong> {formatDate(comp.currentSeason.endDate)}
              </p>
              <p className="matchday-info">
                <strong><i className="fas fa-futbol"></i> هفته جاری:</strong> {comp.currentSeason.currentMatchday}
              </p>
            </div>
            <div className="card-footer">
              <span className={`plan-badge ${comp.plan.toLowerCase().replace('_', '-')}`}>
                {comp.plan}
              </span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Football;