import React, { useState, useEffect } from 'react';
import playersData from '../data/playersData.json'; // وارد کردن داده‌های بازیکنان
import './PlayerGameplay.css'; // وارد کردن استایل‌ها
import {
  Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer
} from 'recharts';

const PlayerGameplay = () => {
  const [selectedPlayer, setSelectedPlayer] = useState(playersData[0]);

  // آماده‌سازی داده‌ها برای رادار چارت
  const radarChartData = selectedPlayer ? [
    { stat: 'پاس', A: selectedPlayer.stats.passing },
    { stat: 'دریبل', A: selectedPlayer.stats.dribbling },
    { stat: 'شوت', A: selectedPlayer.stats.shooting },
    { stat: 'دفاع', A: selectedPlayer.stats.defending },
    { stat: 'قدرت بدنی', A: selectedPlayer.stats.physical },
    { stat: 'سرعت', A: selectedPlayer.stats.speed },
    { stat: 'استقامت', A: selectedPlayer.stats.stamina }
  ] : [];

  const handlePlayerChange = (playerId) => {
    const player = playersData.find(p => p.id === parseInt(playerId));
    setSelectedPlayer(player);
  };

  if (!selectedPlayer) {
    return <div className="player-gameplay-container loading">بازیکن مورد نظر یافت نشد.</div>;
  }
  
  // آیکون برای نمایش پرچم بازیکن (استفاده از image به عنوان placeholder برای پرچم)
  const PlayerFlagIcon = ({ imageUrl, altText }) => {
    if (!imageUrl) return null;
    return <img src={imageUrl} alt={altText} className="player-flag-icon" />;
  };

  return (
    <div className="player-gameplay-container">
      <div className="player-selection-header">
        <h1 className="gameplay-title">صفحه گیم‌پلی بازیکنان</h1>
        <div className="player-selector">
          <label htmlFor="player-select">انتخاب بازیکن:</label>
          <select 
            id="player-select" 
            value={selectedPlayer.id} 
            onChange={(e) => handlePlayerChange(e.target.value)}
          >
            {playersData.map(player => (
              <option key={player.id} value={player.id}>
                {player.name}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="player-details-card">
        <div className="player-header">
          <div className="player-info-main">
            <h2 className="player-name">{selectedPlayer.name}</h2>
            <div className="player-meta">
              <span>تیم: {selectedPlayer.team}</span>
              <span>ملیت: {selectedPlayer.nationality} <PlayerFlagIcon imageUrl={selectedPlayer.image} altText={selectedPlayer.nationality} /></span>
              <span>پست: {selectedPlayer.position}</span>
            </div>
          </div>
          <div className="player-overall-rating">
            <span className="rating-label">امتیاز کلی</span>
            <span className="rating-value">{selectedPlayer.overallRating}</span>
          </div>
        </div>

        <div className="player-content-grid">
          <div className="player-stats-section">
            <h3>آمار بازیکن</h3>
            <div className="radar-chart-wrapper">
              <ResponsiveContainer width="100%" height={300}>
                <RadarChart cx="50%" cy="50%" outerRadius="80%" data={radarChartData}>
                  <PolarGrid stroke="#e0e0e0" />
                  <PolarAngleAxis dataKey="stat" stroke="#666" />
                  <PolarRadiusAxis angle={30} domain={[0, 100]} stroke="#e0e0e0" />
                  <Radar name={selectedPlayer.name} dataKey="A" stroke="#8884d8" fill="#8884d8" fillOpacity={0.6} />
                </RadarChart>
              </ResponsiveContainer>
            </div>
            <div className="individual-stats">
              {Object.entries(selectedPlayer.stats).map(([key, value]) => (
                <div key={key} className="stat-item">
                  <span className="stat-label">{key.charAt(0).toUpperCase() + key.slice(1)}:</span>
                  <span className="stat-value">{value}</span>
                  <div className="stat-bar-container">
                    <div className="stat-bar" style={{ width: `${value}%` }}></div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="player-heatmap-section">
            <h3>نقشه حرارتی (Heatmap)</h3>
            <div className="football-pitch">
              {selectedPlayer.heatmap.map((point, index) => (
                <div
                  key={index}
                  className="heatmap-point"
                  style={{
                    left: `${point.x}%`,
                    top: `${point.y}%`,
                    backgroundColor: `rgba(255, 69, 0, ${point.intensity})`, /* Red-Orange */
                    boxShadow: `0 0 10px 5px rgba(255, 69, 0, ${point.intensity * 0.7})`
                  }}
                ></div>
              ))}
            </div>
            <p className="heatmap-description">
              <i className="fas fa-info-circle"></i> نقاط پررنگ‌تر نشان‌دهنده فعالیت بیشتر بازیکن در آن منطقه است.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PlayerGameplay;